#include <iostream>
#include <string>
#include <vector>

int main()
{
    int m{};
    if (!(std::cin >> m)) return 0;

    std::vector<int> store;      /* raw storage; store.size() is the capacity */
    std::size_t count{ 0 };      /* elements actually in use */
    int grows{ 0 };              /* how many reallocations happened */

    for (int i = 0; i < m; ++i)
    {
        std::string cmd;
        if (!(std::cin >> cmd)) break;

        if (cmd == "push")
        {
            int x{};
            std::cin >> x;
            if (count == store.size())
            {
                std::size_t next{ store.size() == 0 ? 1 : store.size() * 2 };
                std::vector<int> bigger(next, 0);
                for (std::size_t j = 0; j < count; ++j) bigger[j] = store[j];
                store = bigger;
                ++grows;
                std::cout << "push ok grew " << next << "\n";
            }
            else
            {
                std::cout << "push ok\n";
            }
            store[count] = x;
            ++count;
        }
        else if (cmd == "pop")
        {
            if (count == 0) std::cout << "pop empty\n";
            else { --count; std::cout << "pop " << store[count] << "\n"; }
        }
        else if (cmd == "get")
        {
            long long idx{};
            std::cin >> idx;
            if (idx < 0 || idx >= static_cast<long long>(count))
                std::cout << "get range\n";
            else
                std::cout << "get " << store[static_cast<std::size_t>(idx)] << "\n";
        }
        else if (cmd == "state")
        {
            std::cout << "state size " << count
                      << " cap " << store.size()
                      << " grows " << grows << "\n";
        }
    }

    return 0;
}

