import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    m = int(data[pos]); pos += 1

    store = []     # raw storage; len(store) is the capacity
    count = 0      # elements actually in use
    grows = 0
    out = []

    for _ in range(m):
        if pos >= len(data):
            break
        cmd = data[pos]; pos += 1
        if cmd == "push":
            x = int(data[pos]); pos += 1
            if count == len(store):
                nxt = 1 if len(store) == 0 else len(store) * 2
                bigger = [0] * nxt
                for j in range(count):
                    bigger[j] = store[j]
                store = bigger
                grows += 1
                out.append("push ok grew %d" % nxt)
            else:
                out.append("push ok")
            store[count] = x
            count += 1
        elif cmd == "pop":
            if count == 0:
                out.append("pop empty")
            else:
                count -= 1
                out.append("pop %d" % store[count])
        elif cmd == "get":
            idx = int(data[pos]); pos += 1
            if idx < 0 or idx >= count:
                out.append("get range")
            else:
                out.append("get %d" % store[idx])
        elif cmd == "state":
            out.append("state size %d cap %d grows %d" % (count, len(store), grows))

    print("\n".join(out))

main()
